from pathlib import Path
import subprocess,json
ROOT=Path(__file__).resolve().parents[4];Q=Path(__file__).resolve().parent
subjects=[]
for p in (ROOT/'.local-secrets/staging-acceptance').glob('p1-20260916*.json'):
 v=json.loads(p.read_text());assert v['run']=='p1-20260916';subjects += [a['userId'] for a in v['actors']]
assert len(subjects)==8
code="""import pg from 'pg';import {loadDatabaseConfig} from './dist/config.js';import {databaseConnectionOptions} from './dist/db.js';const c=new pg.Client(databaseConnectionOptions(loadDatabaseConfig()));await c.connect();const checksums=(await c.query('select name,checksum from app.schema_migrations order by name desc limit 5')).rows;const roles=(await c.query(\"select pg_has_role('continuity_runtime_staging','continuity_account_service','MEMBER') as can_assume_service,has_column_privilege('continuity_app','app.official_setup_checks','completed','INSERT') as can_import_check,has_column_privilege('continuity_app','app.official_setup_checks','public_id','INSERT') as can_set_public_id\")).rows[0];const remaining=(await c.query(\"select count(*)::int as count from app.identity_accounts where issuer='https://login.rillora.xyz/' and subject=any($1::text[])\",[SUBJECTS])).rows[0].count;const jobs=(await c.query(\"select count(*)::int as count from app.account_deletions where status<>'completed'\")).rows[0].count;console.log(JSON.stringify({checksums,roles,remainingSyntheticIdentities:remaining,pendingDeletionJobs:jobs}));await c.end();""".replace('SUBJECTS',json.dumps(subjects))
s=json.loads(subprocess.check_output(['aws','cloudformation','describe-stacks','--stack-name','RilloraStaging','--profile','rillora-cdk-deploy','--output','json'],text=True))['Stacks'][0];assert s['StackStatus']=='UPDATE_COMPLETE';(Q/'staging-final.json').write_text(json.dumps(s,indent=2)+'\n');o={x['OutputKey']:x['OutputValue'] for x in s['Outputs']}
net={'awsvpcConfiguration':{'subnets':o['PublicSubnetIds'].split(','),'securityGroups':[o['TaskSecurityGroupId']],'assignPublicIp':'ENABLED'}}
over={'containerOverrides':[{'name':'Migration','command':['node','--input-type=module','-e',code]}]}
r=json.loads(subprocess.check_output(['aws','ecs','run-task','--cluster',o['ClusterName'],'--task-definition',o['MigrationTaskDefinitionArn'],'--launch-type','FARGATE','--network-configuration',json.dumps(net),'--overrides',json.dumps(over),'--profile','rillora-staging-operator','--output','json'],text=True));assert not r.get('failures');t=r['tasks'][0];(Q/'final-readback-task.json').write_text(json.dumps({'cluster':o['ClusterName'],'taskArn':t['taskArn']},indent=2)+'\n');print('Final read-only checksum/isolation/fixture-removal verification started.')
